export default function HowItWorks() {
  return (
    <section
      id="how-it-works"
      className="w-full"
      style={{ background: "#ffffff" }}
      aria-labelledby="how-heading"
    >
      <div className="container-inner flex flex-col items-center section-py gap-14">
        {/* Section Head (Figma: max-w-760, gap-16) */}
        <div className="flex flex-col items-center text-center w-full max-w-[760px] gap-4">
          <p
            className="uppercase tracking-widest font-semibold"
            style={{ fontSize: 12, lineHeight: "16px", color: "var(--primary)" }}
          >
            HOW IT WORKS
          </p>
          <h2
            id="how-heading"
            className="text-3xl sm:text-4xl lg:text-[44px]"
            style={{
              fontWeight: 600,
              lineHeight: "52px",
              letterSpacing: "-1px",
              color: "var(--text-primary)",
            }}
          >
            From switchboard to smartphone in three steps
          </h2>
          <p style={{ fontSize: 18, lineHeight: "28px", color: "var(--text-secondary)" }}>
            Autoral Home brings every switch in your home into one place, grouped by room the way your family lives.
          </p>
        </div>

        {/* 3 Step Cards Grid (Figma: card 384x288, gap-24, padding 32px, inner gap 32px) */}
        <div className="w-full grid grid-cols-1 lg:grid-cols-3 gap-6">
          {steps.map((step) => (
            <div
              key={step.num}
              className="flex flex-col rounded-[24px] border figma-card-shadow transition-transform hover:-translate-y-1"
              style={{
                background: "var(--bg-page)",
                borderColor: "var(--border-default)",
                padding: 32,
                gap: 32,
                minHeight: 288,
              }}
            >
              <div className="flex items-center justify-between">
                {/* 56x56 Badge with Blue fill & White vector icon */}
                <div
                  className="flex items-center justify-center shrink-0"
                  style={{
                    width: 56,
                    height: 56,
                    borderRadius: 16,
                    background: "var(--primary)",
                  }}
                >
                  <svg width="28" height="28" viewBox="0 0 28 28" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d={step.path} fill="#ffffff" />
                  </svg>
                </div>

                {/* Big Number in Blue */}
                <span
                  style={{
                    fontSize: 64,
                    fontWeight: 600,
                    lineHeight: "72px",
                    letterSpacing: "-1.5px",
                    color: "var(--primary)",
                  }}
                >
                  {step.num}
                </span>
              </div>

              <div className="flex flex-col gap-2">
                <h3
                  style={{
                    fontSize: 24,
                    fontWeight: 600,
                    lineHeight: "32px",
                    letterSpacing: "-0.2px",
                    color: "var(--text-primary)",
                  }}
                >
                  {step.title}
                </h3>
                <p style={{ fontSize: 16, lineHeight: "26px", color: "var(--text-secondary)" }}>
                  {step.desc}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
